CREATE TABLE strings AS SELECT array_to_string([w[1 + (i * 7) % 16], w[1 + (i * 13) % 16], w[1 + (i * 5) % 16], w[1 + (i * 11) % 16], w[1 + (i * 3) % 16], w[1 + (i * 17) % 16]], ' ') AS s FROM range(0, 10000000) tbl(i), (SELECT ['Grüße', 'naïve', 'mañana', 'Ångström', 'Česko', 'Łódź', 'Café', 'résumé', 'Ελλάδα', 'ΑΘΗΝΑ', 'λόγος', 'Привет', 'ПАЛЯНИЦЯ', 'Київ', 'книга', 'Ärger'] AS w);
